let debug = false;

function esc(value) {
  return String(value ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/\"/g, '&quot;')
    .replace(/'/g, '&#039;');
}

const ARROW_RIGHT_SVG = '<svg viewBox="0 0 16 16" width="16" height="16" fill="none" aria-hidden="true" focusable="false"><path d="M3 8h10m0 0-4-4m4 4-4 4" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"/></svg>';

/**
 * Not sourced from page metadata or any manifest input -- there is no
 * established "call to action label" metadata field to assume on a generic
 * Squiz page (unlike title/description/image/date, which map onto
 * reasonably standard listing metadata). Applied identically to every
 * generated card. See card.spec.md assumption 3.
 */
const ACTION_TEXT = 'Find out more';

/**
 * `metadata.Image` holds an asset ID (a Matrix asset-picker metadata field),
 * not a ready-made image object -- so the actual file URL is resolved via a
 * dedicated fns.resolveMatrixAssetById(assetId) call, the same way a Squiz
 * keyword would resolve an asset ID to its URL, rather than read directly
 * off the page asset like the rest of card content.
 */
function toCardImage(asset) {
  if (!asset) return null;
  const url = asset.url || (Array.isArray(asset.urls) ? asset.urls[0] : '') || '';
  if (!url) return null;
  return {
    url,
    alt: asset.alt || asset.name || '',
    width: asset.width || null,
    height: asset.height || null,
  };
}

async function resolveCardImage(assetId, fns) {
  if (!assetId || typeof fns?.resolveMatrixAssetById !== 'function') return null;
  let result;
  try {
    result = await fns.resolveMatrixAssetById(assetId, ['url', 'urls', 'name', 'alt', 'witdh', 'height']);
  } catch(err) {
    console.error(err)
    return null;
  }
  return toCardImage(result.data);
}

/**
 * Per the real Matrix asset schema, `metadata` is a key-value map where
 * every value is an array of strings (Matrix metadata fields are
 * multi-value by design), e.g. {Category: ["News"], Date: ["17 Feb 2025"]}
 * -- not a flat {category: "News"} shape. This reads the first value for
 * a given key. The key NAMES themselves (Category/Date/Description below)
 * are still unconfirmed -- Matrix metadata field names are site-specific,
 * defined by whoever set up the metadata schema for these pages -- but the
 * *shape* (string-array values) is now a confirmed schema fact, not a guess.
 * See card.spec.md assumption 1.
 */
function firstMetadataValue(metadata, key) {
  const value = metadata?.[key];
  return Array.isArray(value) ? (value[0] || '') : '';
}

/**
 * Maps one resolved Squiz page asset onto card content. `name`/`url` are
 * confirmed schema fields; the metadata key names (Image/Category/Date/
 * Description) are still unconfirmed -- see card.spec.md assumption 1. Any
 * field absent from the resolved asset is simply omitted from the card
 * (never throws).
 */
async function toCard(page, fns) {
  if (!page) return null;
  const metadata = page.metadata || {};
  const imageAssetId = firstMetadataValue(metadata, 'Image');

  return {
    title: page.name || '',
    description: firstMetadataValue(metadata, 'Description'),
    image: await resolveCardImage(imageAssetId, fns),
    date: firstMetadataValue(metadata, 'Date'),
    tagLabel: firstMetadataValue(metadata, 'Category'),
    href: page.url || '',
    actionText: ACTION_TEXT,
  };
}

/**
 * Per the real Matrix asset schema, a resolved asset's direct child assets
 * (when requested/populated) arrive under `include_dependents` -- "All
 * direct dependent child assets of the asset in normalized asset format"
 * -- not a `children` key as originally assumed. Whether `resolveUri()`
 * (as opposed to `resolveMatrixAssetById(id, ['include_dependents'])`)
 * actually populates this by default against a real Matrix backend is
 * still unconfirmed -- see card.spec.md assumption 4.
 */
function isParentPage(resolved) {
  return Array.isArray(resolved?.include_dependents);
}

/**
 * Resolves the `pageSources` manifest field into a flat list of card data.
 * Each source resolves independently and in parallel: a single-page source
 * contributes one card, a parent-page source contributes one card per
 * child page. Best-effort -- any source that fails to resolve (or
 * `info.fns` not being available at all) contributes nothing rather than
 * throwing.
 */
async function resolveCards(pageSources, fns) {
  if (!Array.isArray(pageSources) || pageSources.length === 0) return [];
  if (typeof fns?.resolveUri !== 'function') return [];

  const resolvedLists = await Promise.all(pageSources.map(async (source) => {
    if (!source) return [];

    let resolved;
    try {
      resolved = await fns.resolveUri(source);
    } catch {
      return [];
    }
    if (!resolved) return [];

    if (isParentPage(resolved)) {
      const childCards = await Promise.all(resolved.include_dependents.map((child) => toCard(child, fns)));
      return childCards.filter(Boolean);
    }
    
    const card = await toCard(resolved, fns);
    return card ? [card] : [];
  }));

  return resolvedLists.flat();
}

function renderCard(card) {
  const resolvedImage = card.image;
  const titleId = `card-title-${Math.random().toString(36).slice(2, 9)}`;

  const imageHtml = resolvedImage
    ? `
    <div class="card__image">
      <img src="${esc(resolvedImage.url)}" alt="${esc(resolvedImage.alt)}"${resolvedImage.width ? ` width="${resolvedImage.width}"` : ''}${resolvedImage.height ? ` height="${resolvedImage.height}"` : ''} />
    </div>`
    : '';

  const hasHeader = Boolean(card.tagLabel || card.date);
  const headerHtml = hasHeader
    ? `
      <div class="card__header">
        ${card.tagLabel ? `<span class="card__tag">${esc(card.tagLabel)}</span>` : ''}
        ${card.date ? `<span class="card__date">${esc(card.date)}</span>` : ''}
      </div>`
    : '';

  const descriptionHtml = card.description
    ? `<p class="card__description">${esc(card.description)}</p>`
    : '';

  const footerHtml = card.actionText
    ? `
      <div class="card__footer">
        <span class="card__action">${esc(card.actionText)} <span class="card__action-icon">${ARROW_RIGHT_SVG}</span></span>
      </div>`
    : '';

  const innerHtml = `${imageHtml}
    <div class="card__content">${headerHtml}
      <div class="card__body">
        <h3 class="card__title" id="${titleId}">${esc(card.title)}</h3>
        ${descriptionHtml}
      </div>${footerHtml}
    </div>`;

  return card.href
    ? /*html*/`<a class="card" href="${esc(card.href)}" aria-labelledby="${titleId}">${innerHtml}</a>`
    : /*html*/`<article class="card">${innerHtml}</article>`;
}

/**
 * Purely manual, per-item render -- no resolution step, unlike renderCard()
 * above. See card.spec.md assumption 6 for the icon/label/href field-name
 * and Font Awesome classic/thin convention inference.
 */
function renderMiniCard(item) {
  const { icon = '', label = '', href = '' } = item || {};
  const iconHtml = icon ? `<i class="fa-thin fa-${esc(icon)}"></i>` : '';

  const innerHtml = `
    <span class="mini-card__icon" aria-hidden="true">${iconHtml}</span>
    <span class="mini-card__label" data-sq-field="label">${esc(label)}</span>`;

  return href
    ? /*html*/`<a class="mini-card" href="${esc(href)}">${innerHtml}</a>`
    : /*html*/`<div class="mini-card">${innerHtml}</div>`;
}

export default {
  async main(input = {}, info = {}) {
    if (input.debug) {
      debug = true;
      delete info.debug;
    }
    const { cardMode = 'pages', pageSources = [], miniCards = [] } = input;

    if (cardMode === 'miniCards') {
      const items = Array.isArray(miniCards) ? miniCards : [];
      debug = false;
      return /*html*/`
<div class="card-grid">
  ${items.map(renderMiniCard).join('')}
</div>
`;
    }

    const cards = await resolveCards(pageSources, info.fns);
    debug = false;
    return /*html*/`
<div class="card-grid">
  ${cards.map(renderCard).join('')}
</div>
`;
  },
};
