import squizStoryRenderer from '@ntgovernment/squiz-factory/plugins/squizStoryRenderer';
import squizInfoMock from '@ntgovernment/squiz-factory/plugins/squizInfo.mock';
import comp from './main.js';


const mockImgIdPrefix = 'mock-img-';
const FAKE_ASSETS_By_ID = {
  // populated by `fakePage` calls
};
/**
 * Shaped to match the real MatrixAssetSchema.json (confirmed by inspecting
 * the installed @squiz/dxp-cli-next's compiled source -- see the spec's
 * assumption 1/5): `name` (not `title`), `thumbnail` as a direct {url, alt}
 * object (not SquizImage/imageVariations), and `metadata` as a key-value
 * map of string ARRAYS (not flat values).
 */
function fakePage({ id, name, category, date, description, mockImage }) {
  const metadata = {
    Category: [category],
    Date: [date],
    Description: [description],
  };
  let imgId;
  if (mockImage) {
    const imgSrc = `https://picsum.photos/id/${id}/640/480`;
    imgId = mockImgIdPrefix + id;
    FAKE_ASSETS_By_ID[imgId] = {
      url: imgSrc,
      urls: [`https://picsum.photos/id/${id}/640/480`],
      alt: `${name} thumbnail`,
    };
    metadata.Image = [imgId];
  }
  return {
    id: String(id),
    type: 'pageStandard',
    name,
    url: `https://example.com/pages/${id}`,
    thumbnail: imgId ? FAKE_ASSETS_By_ID[imgId] : null,
    metadata,
    child_count: 0,
  };
}

/**
 * This component resolves each entry in `pageSources` at render time via
 * info.fns.resolveUri(source), a real DXP edge capability. In the real
 * local dev-ui this is backed by the manifest's own `mockedUris` field
 * (see manifest.json / card.spec.md assumption 5) -- these Storybook fakes
 * are a separate, project-controlled mock that exists purely so the
 * multi-source/parent-page-expansion *logic* in main.js can be verified
 * here without a real Matrix backend. See the spec's assumptions.
 */
const FAKE_ASSETS = {
  'matrix-asset://ntg/1001': fakePage({
    mockImage: true,
    id: 1015,
    name: 'Community Consultation Opens for Major Project',
    category: 'News',
    date: '17 Feb 2025',
    description: 'Residents invited to provide feedback on proposed infrastructure improvements in the greater Darwin area.',
  }),
  'matrix-asset://ntg/2001': {
    id: '2001',
    type: 'folder',
    name: 'News section',
    url: 'https://example.com/news',
    child_count: 3,
    include_dependents: [
      fakePage({ mockImage: true, id: 1016, name: 'Annual Territory Day Celebrations', category: 'Event', date: '15 Dec 2025', description: 'Join us for fireworks, live music, and family activities at Mindil Beach.' }),
      fakePage({ mockImage: true,id: 1018, name: 'Understanding Territory Heritage Programs', category: 'News', date: '28 Nov 2025', description: 'Explore how the NT Government is preserving indigenous heritage sites.' }),
      fakePage({ mockImage: true,id: 1019, name: 'Road Closures This Weekend', category: 'Alert', date: '3 Dec 2025', description: 'Temporary closures on the Stuart Highway for scheduled maintenance work.' }),
    ],
  },
  'matrix-asset://ntg/3001': {
    id: '3001',
    type: 'folder',
    name: 'Empty section',
    url: 'https://example.com/empty',
    child_count: 0,
    include_dependents: [],
  }
};

/**
 * squizStoryRenderer's installed signature only takes `main` -- it does not
 * accept a second (resolveUri-mock) constructor argument, so that argument
 * was previously silently ignored. The returned render function's own
 * `info` parameter must be supplied at each call site instead; without it,
 * every story rendered an empty grid (`resolveCards` bails out as soon as
 * `typeof fns?.resolveUri !== 'function'`) even though the separately
 * precomputed "Show code" HTML (built via a direct `comp.main(args,
 * mockInfo)` call below) looked correct.
 */
const squiz = squizStoryRenderer(comp.main);
const mockInfo = squizInfoMock({
  mock: {
    resolveUri(uri) {
      return FAKE_ASSETS[uri] ?? null;
    },
    resolveMatrixAssetById(assetId, props = []) {
      /**
       * Last example I was shown from squiz was this result shape
       * fail seemd to be ok: true so doing same tho it make ok pretty useless
       */
      if (FAKE_ASSETS_By_ID[assetId])
        return {ok: true, data: FAKE_ASSETS_By_ID[assetId]};
      return {ok:true, data: null}
    }
  }
});

export default {
  title: 'dxp/Card',
};

const singlePageArgs = { debug: false, pageSources: ['matrix-asset://ntg/1001'] };
const singlePageHtml = await squiz.markup(singlePageArgs, mockInfo);

export const SinglePage = {
  render: (args) => squiz(args, mockInfo),
  args: singlePageArgs,
  argTypes: {
    debug: { control: 'boolean' },
    pageSources: {
      control: 'object',
      description: 'Array of matrix-asset-uri strings, each an individually-picked page or a parent page whose children all become cards. Only these demo URIs resolve to anything in this Storybook preview (mocked): matrix-asset://ntg/1001, matrix-asset://ntg/2001, matrix-asset://ntg/3001.',
    },
  },
  parameters: {
    docs: {
      description: { story: 'pageSources has one entry pointing directly at a single page -- one card, populated entirely from that page\'s own metadata (title, description, image, date, category, url). Hover/tab-focus the card to see the hover/focus states.' },
      source: { code: singlePageHtml, language: 'html', type: 'code' },
    },
  },
};

const parentPageArgs = { debug: true, pageSources: ['matrix-asset://ntg/2001'] };
const parentPageHtml = await squiz.markup(parentPageArgs, mockInfo);

export const ParentPage = {
  render: () => squiz(parentPageArgs, mockInfo),
  parameters: {
    docs: {
      description: { story: 'pageSources has one entry pointing at a parent/section page; every child page becomes its own card, arranged in the responsive grid (3 columns desktop, 2 tablet, 1 mobile).' },
      source: { code: parentPageHtml, language: 'html', type: 'code' },
    },
  },
};

const mixedArgs = { pageSources: ['matrix-asset://ntg/1001', 'matrix-asset://ntg/2001'] };
const mixedHtml = await squiz.markup(mixedArgs, mockInfo);

export const Mixed = {
  render: () => squiz(mixedArgs, mockInfo),
  parameters: {
    docs: {
      description: { story: 'pageSources combines one individually-picked page with one parent section -- the grid is the union of both (the individual page\'s card plus one card per child page).' },
      source: { code: mixedHtml, language: 'html', type: 'code' },
    },
  },
};

const emptySectionArgs = { pageSources: ['matrix-asset://ntg/3001'] };
const emptySectionHtml = await squiz.markup(emptySectionArgs, mockInfo);

export const EmptySection = {
  render: () => squiz(emptySectionArgs, mockInfo),
  parameters: {
    docs: {
      description: { story: 'A parent page with no children resolves to an empty grid, not an error.' },
      source: { code: emptySectionHtml, language: 'html', type: 'code' },
    },
  },
};

const unresolvableArgs = { pageSources: ['matrix-asset://ntg/9999999'] };
const unresolvableHtml = await squiz.markup(unresolvableArgs, mockInfo);

export const Unresolvable = {
  render: () => squiz(unresolvableArgs, mockInfo),
  parameters: {
    docs: {
      description: { story: 'A source that fails to resolve at all contributes nothing, rendering an empty grid rather than throwing.' },
      source: { code: unresolvableHtml, language: 'html', type: 'code' },
    },
  },
};

/**
 * cardMode: "miniCards" -- manually-authored icon + label link cards, no
 * page resolution involved. See card.spec.md assumption 6.
 */
const miniCardsArgs = {
  cardMode: 'miniCards',
  miniCards: [
    { icon: 'briefcase', label: 'Grant applicants', href: '#' },
    { icon: 'earth-americas', label: 'Service providers', href: '#' },
    { icon: 'circle-info', label: 'Get in touch', href: '#' },
  ],
};
const miniCardsHtml = await squiz.markup(miniCardsArgs, mockInfo);

export const MiniCards = {
  render: () => squiz(miniCardsArgs, mockInfo),
  argTypes: {
    cardMode: { control: 'radio', options: ['pages', 'miniCards'] },
    miniCards: {
      control: 'object',
      description: 'Array of { icon, label, href } -- icon is a Font Awesome classic/thin name without the "fa-" prefix. Only used when cardMode is "miniCards".',
    },
  },
  parameters: {
    docs: {
      description: { story: 'cardMode "miniCards" switches the grid to manually-authored icon + label link items, in the same responsive 3/2/1-column layout as the page-derived "pages" mode. No resolveUri call happens in this mode.' },
      source: { code: miniCardsHtml, language: 'html', type: 'code' },
    },
  },
};

const miniCardsNoLinkArgs = {
  cardMode: 'miniCards',
  miniCards: [
    { icon: 'briefcase', label: 'Grant applicants', href: '#' },
    { icon: '', label: 'No icon, no link', href: '' },
  ],
};
const miniCardsNoLinkHtml = await squiz.markup(miniCardsNoLinkArgs, mockInfo);

export const MiniCardsNoLink = {
  render: () => squiz(miniCardsNoLinkArgs, mockInfo),
  parameters: {
    docs: {
      description: { story: 'An item with no href renders as a non-interactive div instead of a link; an item with no icon simply omits the icon markup -- both degrade gracefully rather than erroring.' },
      source: { code: miniCardsNoLinkHtml, language: 'html', type: 'code' },
    },
  },
};
